336	
337	    /** Set the sheet's proof threshold (null: none) from a date (null: the sheet's today), the
338	     *  sheet created first if it was never loaded; a claim dated from then on to the next from-date
339	     *  whose due is above it cannot be settled or approved while it has no proof. */
340	    @Transactional
341	    public BigDecimal setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
342	        Sheet sheet = sheets.load(sheetId, user);
343	        sheets.lock(sheetId);
344	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
345	        record(sheet, user, PROOF_THRESHOLD, scaled == null ? "" : scaled.toPlainString(), from);
346	        return scaled;
347	    }
348	
349	    /** Set a grade's proof threshold (null: none, the grade uses the sheet's) from a date (null:
350	     *  the sheet's today), the sheet created first if it was never loaded; a claim dated from then
351	     *  on to the next from-date whose person's grade then is this one and whose due is above it
352	     *  cannot be settled or approved while it has no proof. */
353	    @Transactional
354	    public BigDecimal setGradeProofThreshold(String sheetId, String user, String grade, BigDecimal threshold, LocalDate from) {
355	        Sheet sheet = sheets.load(sheetId, user);
356	        sheets.lock(sheetId);
357	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
358	        record(sheet, user, PROOF_THRESHOLD_OF_GRADE + grade, scaled == null ? "" : scaled.toPlainString(), from);
359	        return scaled;
360	    }
361	
362	    /** Set the sheet's note threshold (null: none) from a date (null: the sheet's today), the
363	     *  sheet created first if it was never loaded; a claim dated from then on to the next from-date
364	     *  whose due is above it cannot be opened while its note is empty. */
365	    @Transactional
366	    public BigDecimal setNoteThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
367	        Sheet sheet = sheets.load(sheetId, user);
368	        sheets.lock(sheetId);
369	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
370	        record(sheet, user, NOTE_THRESHOLD, scaled == null ? "" : scaled.toPlainString(), from);
371	        return scaled;
372	    }
373	
374	    /** Every value recorded for the sheet's dated settings, by key, each key's by from-date. */
375	    @Transactional(readOnly = true)
376	    public Map<String, List<DatedSetting>> datedSettings(String sheetId) {
377	        return sheets.find(sheetId).map(Sheet::getDatedSettings).orElse(Map.of());
378	    }
379	
380	    @Transactional(readOnly = true)
381	    public List<SheetRole> roles(String sheetId) {
382	        return roles.findBySheetIdOrderByUserAsc(sheetId);
383	    }
384	
385	    /** The role a user name acts in on the sheet: a steward while a steward's delegation to it
386	     *  covers the sheet's today, else the role it holds. */
387	    @Transactional(readOnly = true)
388	    public Role roleOf(String sheetId, String user) {
389	        Role held = heldRoleOf(sheetId, user);
390	        return held != Role.STEWARD && delegatorOf(sheetId, user) != null ? Role.STEWARD : held;
391	    }
392	
393	    /** The role a user name holds on the sheet in its own right: a clerk unless set otherwise. */
394	    @Transactional(readOnly = true)
395	    public Role heldRoleOf(String sheetId, String user) {
396	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
397	    }
398	
399	    /** The steward whose delegation the user name acts under on the sheet's today; null when it
400	     *  acts in its own right (a steward itself, or no delegation covers the sheet's today). */
401	    @Transactional(readOnly = true)
402	    public String delegatorOf(String sheetId, String user) {
403	        List<SheetDelegation> made = delegations.findBySheetIdAndUserOrderByIdDesc(sheetId, user);
404	        if (made.isEmpty() || heldRoleOf(sheetId, user) == Role.STEWARD) {
405	            return null;
406	        }
407	        LocalDate today = sheets.today(sheetId);
408	        return made.stream().filter(d -> d.covers(today)).map(SheetDelegation::getSteward).findFirst().orElse(null);
409	    }
410	
411	    @Transactional(readOnly = true)
412	    public List<SheetDelegation> delegations(String sheetId) {
413	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
414	    }
415	
416	    /** Delegate the steward role to a user name from a date (null: the sheet's today) to a date
417	     *  (null: the from-date), inclusive, the sheet created first if it was never loaded; refused
418	     *  (403) unless the user is a steward in its own right, and (400) for a to-date before the
419	     *  from-date. */
420	    @Transactional
421	    public SheetDelegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
422	        sheets.load(sheetId, user);
423	        if (heldRoleOf(sheetId, user) != Role.STEWARD) {
424	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may delegate");
425	        }
426	        LocalDate start = from == null ? sheets.today(sheetId) : from;
427	        LocalDate end = to == null ? start : to;
428	        if (end.isBefore(start)) {
429	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date");
430	        }
431	        SheetDelegation made = delegations.saveAndFlush(new SheetDelegation(sheetId, name, user, start, end));
432	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name
433	                + " from=" + start + " to=" + end);
434	        return made;
435	    }
436	
437	    /** The sheet's holidays, earliest first. */
438	    @Transactional(readOnly = true)
439	    public List<LocalDate> holidays(String sheetId) {
440	        return holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(SheetHoliday::getDay).toList();
441	    }
442	
443	    /** Add a holiday to the sheet, the sheet created first if it was never loaded; refused (409)
444	     *  when the date is on its list already. {@link HolidayAdded} is published once it is on the
445	     *  list, re-fixing the due-by of the claims due on or after it. */
446	    @Transactional
447	    public LocalDate addHoliday(String sheetId, String user, LocalDate day) {
448	        sheets.load(sheetId, user);
449	        sheets.lock(sheetId);
450	        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
451	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The date is a holiday already");
452	        }
453	        holidays.saveAndFlush(new SheetHoliday(sheetId, day));
454	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + day);
455	        events.publishEvent(new HolidayAdded(sheetId, user, day));
456	        return day;
457	    }
458	
459	    /** The sheet's void reasons, in the order they were added. */
460	    @Transactional(readOnly = true)
461	    public List<String> voidReasons(String sheetId) {
462	        return voidReasons.findBySheetIdOrderByIdAsc(sheetId).stream().map(SheetVoidReason::getReason).toList();
463	    }
464	
465	    /** Whether the reason is on the sheet's list of void reasons. */
466	    @Transactional(readOnly = true)
467	    public boolean isVoidReason(String sheetId, String reason) {
468	        return voidReasons.existsBySheetIdAndReason(sheetId, reason);
469	    }
470	
471	    /** Add a void reason to the sheet, the sheet created first if it was never loaded; refused (409)
472	     *  when the reason is on its list already. */
473	    @Transactional
474	    public String addVoidReason(String sheetId, String user, String reason) {
475	        sheets.load(sheetId, user);
476	        sheets.lock(sheetId);
477	        if (voidReasons.existsBySheetIdAndReason(sheetId, reason)) {
478	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The reason is on the list already");
479	        }
480	        voidReasons.saveAndFlush(new SheetVoidReason(sheetId, reason));
481	        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + reason);
482	        return reason;
483	    }
484	
485	    /** Archive the sheet, the sheet created first if it was never loaded; refused (403) unless the
486	     *  user acts as a steward, and (409) when it is archived already. */
487	    @Transactional
488	    public Sheet archive(String sheetId, String user) {
489	        Sheet sheet = sheets.load(sheetId, user);
490	        sheets.lock(sheetId);
491	        if (roleOf(sheetId, user) != Role.STEWARD) {
492	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may archive the sheet");
493	        }
494	        if (sheet.isArchived()) {
495	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived already");
496	        }
497	        sheet.archive();
498	        sheets.flush();
499	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + sheetId + " by=" + user);
500	        return sheet;
501	    }
502	
503	    /** Whether the user name is a viewer on the sheet: sees it and may change nothing on it. */
504	    @Transactional(readOnly = true)
505	    public boolean isViewer(String sheetId, String user) {
506	        return roleOf(sheetId, user) == Role.VIEWER;
507	    }
508	
509	    /** Give a user name a role on the sheet, the sheet created first if it was never loaded. */
510	    @Transactional
511	    public SheetRole setRole(String sheetId, String user, String name, Role role) {
512	        sheets.load(sheetId, user);
513	        SheetRole held = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
514	        try {
515	            if (held == null) {
516	                held = roles.saveAndFlush(new SheetRole(sheetId, name, role));
517	            } else {
518	                held.setRole(role);
519	                roles.flush();
520	            }
521	        } catch (DataIntegrityViolationException e) {
522	            // set by another user at the same moment
523	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Role changed at the same moment");
524	        }
525	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.key());
526	        return held;
527	    }
528	
529	    /** Whether a user may settle a claim showing a due (null: n/a, within any limit): a steward
530	     *  settles anything, a clerk only a due at or below the sheet's clerk limit, if it has one. */
531	    @Transactional(readOnly = true)
532	    public boolean maySettle(String sheetId, String user, BigDecimal due) {
533	        if (due == null || roleOf(sheetId, user) == Role.STEWARD) {
534	            return true;
535	        }
536	        BigDecimal limit = clerkLimit(sheetId);
537	        return limit == null || due.compareTo(limit) <= 0;
538	    }
539	
540	    /** The roles the sheet's permission matrix sets for each action, as set; an action left blank
541	     *  (keeping its standing rule) is left out. */
542	    @Transactional(readOnly = true)
543	    public Map<Permission, String> permissions(String sheetId) {
544	        Map<Permission, String> out = new EnumMap<>(Permission.class);
545	        permissions.findBySheetId(sheetId).forEach(p -> out.put(p.getAction(), p.getRoles()));
546	        return out;
547	    }
548	
549	    /** Set the roles that may take an action (blank: its standing rule), comma separated, the
550	     *  sheet created first if it was never loaded; not dated, it applies from now on. */
551	    @Transactional
552	    public String setPermission(String sheetId, String user, Permission action, String rolesText) {
553	        sheets.load(sheetId, user);
554	        sheets.lock(sheetId);
555	        SheetPermission held = permissions.findBySheetIdAndAction(sheetId, action.key()).orElse(null);
556	        if (rolesText.isEmpty()) {
557	            if (held != null) {
558	                permissions.delete(held);
559	            }
560	        } else if (held == null) {
561	            permissions.save(new SheetPermission(sheetId, action, rolesText));
562	        } else {
563	            held.setRoles(rolesText);
564	        }
565	        permissions.flush();
566	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
567	                + " key=" + PERMISSION + action.key() + " value=" + rolesText);
568	        return rolesText;
569	    }
570	
571	    /** Whether the user's role may take the action: as the permission matrix sets it, else by its
572	     *  standing rule. */
573	    @Transactional(readOnly = true)
574	    public boolean mayTake(String sheetId, String user, Permission action) {
575	        Role role = roleOf(sheetId, user);
576	        return permissions.findBySheetIdAndAction(sheetId, action.key())
577	                .map(p -> p.roleSet().contains(role))
578	                .orElseGet(() -> action.standing().contains(role));
579	    }
580	
581	    /** Refuse (403) the action unless the user's role may take it. */
582	    @Transactional(readOnly = true)
583	    public void refuseUnlessAllowed(String sheetId, String user, Permission action) {
584	        if (!mayTake(sheetId, user, action)) {
585	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
586	                    "The user's role may not " + action.key() + " on this sheet");
587	        }
588	    }
589	}
